package com.meterflow.invoicing;
import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="invoice_adjustments") public class InvoiceAdjustment{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(nullable=false)private String customerId;@Column(nullable=false)private String period;@Column(nullable=false)private String currency;@Column(nullable=false,precision=18,scale=2)private BigDecimal subtotal;@Column(nullable=false,precision=18,scale=2)private BigDecimal tax;@Column(nullable=false,precision=18,scale=2)private BigDecimal total;@Column(nullable=false)private Instant createdAt=Instant.now();@Column(nullable=false,length=500)private String reason;protected InvoiceAdjustment(){}public InvoiceAdjustment(String c,String p,String currency,BigDecimal sub,BigDecimal tax,String reason){customerId=c;period=p;this.currency=currency;subtotal=sub;this.tax=tax;total=sub.add(tax);this.reason=reason;}public UUID getId(){return id;}public String getCustomerId(){return customerId;}public String getPeriod(){return period;}public String getCurrency(){return currency;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getTax(){return tax;}public BigDecimal getTotal(){return total;}public Instant getCreatedAt(){return createdAt;}public String getReason(){return reason;}}
